#include "../src/fluid.hpp"
#include "../src/scene.hpp"
using namespace water;
int main(){Config c;c.threads=4;c.dx=.05f;c.whitewater=false;Solver s(makeHeroScene(),c);s.initialize();s.emit(.008f);s.transferToGrid();s.addForces(.008f);s.buildPressureSystem(.008f);std::vector<float>b=s.rhs; s.pressureSolve(.008f);std::vector<std::pair<float,int>>bad;for(int n:s.active){int x=n%s.nx,y=n/s.nx%s.ny,z=n/(s.nx*s.ny);bad.push_back({std::abs(s.divergence(x,y,z)),n});}std::sort(bad.rbegin(),bad.rend());s.multiply(s.pressure,s.workQ);for(int k=0;k<20;k++){int n=bad[k].second,x=n%s.nx,y=n/s.nx%s.ny,z=n/(s.nx*s.ny);std::cout<<x<<','<<y<<','<<z<<" p="<<s.pressure[n]<<" div="<<s.divergence(x,y,z)<<" eq="<<b[n]-s.workQ[n]<<" diag="<<s.diag[n]<<" rhs="<<b[n]<<" p0="<<s.phi.a[n]<<"\n";for(int a=0;a<3;a++)for(int dir:{0,1}){int q[3]={x,y,z};q[a]+=dir;auto&f=s.grid[a];int fn=f.value.index(q[0],q[1],q[2]);std::cout<<"face "<<a<<dir<<" fixed="<<int(f.fixed[fn])<<" open="<<f.open.a[fn]<<" vel="<<f.value.a[fn]<<"\n";}}}
